/**
 * @brief 基座位姿提供者接口
 * 用于解耦motion和navigation之间的依赖
 * motion通过此接口获取base_state，而不直接依赖navigation
 */
class BaseStateProvider {
 public:
  using GetBaseStateFunc = std::function<std::vector<double>()>;

  /**
   * @brief 设置获取基座位姿的回调函数
   * @param func 回调函数，返回基座位姿（7维向量：[x, y, z, qx, qy, qz, qw]）
   */
  static void set_get_base_state_callback(GetBaseStateFunc func) { get_base_state_func_ = func; }

  /**
   * @brief 获取基座位姿
   * @return 基座位姿向量，如果未设置回调则返回空向量
   */
  static std::vector<double> get_base_state() {
    if (get_base_state_func_) {
      return get_base_state_func_();
    }
    return {};
  }

  /**
   * @brief 检查是否已设置回调
   */
  static bool is_available() { return get_base_state_func_ != nullptr; }

 private:
  static GetBaseStateFunc get_base_state_func_;
};

/**
 * @brief 整机各关节状态提供者接口
 * 用于解耦motion和robot之间的依赖
 * motion通过此接口获取joint_state_map，而不直接依赖robot
 */
class JointStateProvider {
 public:
  // 回调类型：获取整机各关节状态的函数签名
  // 参数：输出参数，按关节分组的关节状态映射（由调用方提供并填充）
  // 返回：ControlStatus，表示回调执行结果（如 SUCCESS / DATA_FETCH_FAILED / INVALID_INPUT 等）
  using GetWholeBodyJointStateFunc =
      std::function<ControlStatus(std::unordered_map<std::string, JointStateMessage>& joint_state_map)>;

  /**
   * @brief 设置获取整机关节状态的回调函数
   * @param func 回调函数，签名见 `GetWholeBodyJointStateFunc`
   *
   * Motion 模块通过此回调从外部（例如 robot driver 或 navigation）获取
   * 整机的关节状态信息，从而避免直接依赖具体的上层模块实现。
   */
  static void set_get_whole_body_joint_state_callback(GetWholeBodyJointStateFunc func) {
    get_whole_body_joint_state_func_ = func;
  }

  /**
   * @brief 获取整机关节状态
   * @param[out] joint_state_map 由回调填充的关节状态映射
   * @return ControlStatus 回调返回的状态；若未设置回调则返回 `ControlStatus::INVALID_INPUT`
   */
  static ControlStatus get_whole_body_joint_state(std::unordered_map<std::string, JointStateMessage>& joint_state_map) {
    if (get_whole_body_joint_state_func_) {
      return get_whole_body_joint_state_func_(joint_state_map);
    }
    return ControlStatus::INVALID_INPUT;
  }

  /** 与 GalbotRobot::get_joint_positions / WbcBase::get_joint_positions 对齐 */
  using GetJointPositionsFunc =
      std::function<std::vector<double>(const std::vector<std::string>& joint_groups,
                                        const std::vector<std::string>& joint_names)>;

  static void set_get_joint_positions_callback(GetJointPositionsFunc func) {
    get_joint_positions_func_ = std::move(func);
  }

  /**
   * @brief 按关节组/关节名查询当前位置（与 robot 实现一致）
   * @return 未注册回调时返回空向量；否则由回调返回（长度由调用方校验）
   */
  static std::vector<double> get_joint_positions(const std::vector<std::string>& joint_groups,
                                                 const std::vector<std::string>& joint_names) {
    if (get_joint_positions_func_) {
      return get_joint_positions_func_(joint_groups, joint_names);
    }
    return {};
  }

 private:
  static GetWholeBodyJointStateFunc get_whole_body_joint_state_func_;
  static GetJointPositionsFunc get_joint_positions_func_;
};

